421	  function renderFullKit() {
422	    const main = document.getElementById('main');
423	
424	    if (!contract.length) {
425	      main.innerHTML = `<div class="catalog-home empty-state">
426	        <p>No components in the contract yet.</p>
427	        <p>Run <code>/extract</code> to populate the contract, then reload this page.</p>
428	      </div>`;
429	      return;
430	    }
431	
432	    let html = `<div class="component-detail">
433	      <h2>Full UI Kit</h2>
434	      <p style="font-size:var(--ui-size-sm);color:var(--pv-text-muted);margin-bottom:2rem;">
435	        Every component in one page, grouped by tier, every variant rendered live from each component's <code>demo.html</code>. Generated from <code>${prefix}-contract.js</code>, refresh after any extraction to see the latest.
436	      </p>`;
437	
438	    for (const tier of TIERS) {
439	      const items = byTier(tier);
440	      if (!items.length) continue;
441	
442	      html += `<div class="tier-group"><h3>${cap(tier)}s</h3>`;
443	
444	      for (const c of items) {
445	        const folderName = c.element.slice(c.prefix.length + 1);
446	        const demoPath = `../library/elements/${folderName}/demo.html`;
447	
448	        html += `<div class="section">
449	          <div class="section-head">
450	            <h3 style="text-transform:none;color:var(--pv-text);font-size:var(--ui-size-base);font-weight:var(--ui-weight-strong);">
451	              ${c.name}
452	              <span class="tier-tag tier-${c.atomic}" style="margin-left:0.5rem;">${c.atomic}</span>
453	            </h3>
454	            <a href="#${c.element}">Details &amp; API &rarr;</a>
455	          </div>
456	          <div class="demo-frame">
457	            <iframe src="${demoPath}" onload="resizeFrame(this)"></iframe>
458	          </div>
459	        </div>`;
460	      }
461	
462	      html += `</div>`;
463	    }
464	
465	    html += `</div>`;
466	    main.innerHTML = html;
467	  }
468	
469	  function renderComponent(element) {
470	    const entry = contract.find(c => c.element === element);
471	    if (!entry) {
472	      renderHome();
473	      return;
474	    }
