function renderFullKit() {
  const main = document.getElementById('main');

  if (!contract.length) {
    main.innerHTML = `<div class="catalog-home empty-state">
      <p>No components in the contract yet.</p>
      <p>Run <code>/extract</code> to populate the contract, then reload this page.</p>
    </div>`;
    return;
  }

  let html = `<div class="component-detail">
    <h2>Full UI Kit</h2>
    <p style="font-size:var(--ui-size-sm);color:var(--pv-text-muted);margin-bottom:2rem;">
      Every component in one page, grouped by tier, every variant rendered live from each component's <code>demo.html</code>. Generated from <code>${prefix}-contract.js</code>, refresh after any extraction to see the latest.
    </p>`;

  for (const tier of TIERS) {
    const items = byTier(tier);
    if (!items.length) continue;

    html += `<div class="tier-group"><h3>${cap(tier)}s</h3>`;

    for (const c of items) {
      const folderName = c.element.slice(c.prefix.length + 1);
      const demoPath = `../library/elements/${folderName}/demo.html`;

      html += `<div class="section">
        <div class="section-head">
          <h3 style="text-transform:none;color:var(--pv-text);font-size:var(--ui-size-base);font-weight:var(--ui-weight-strong);">
            ${c.name}
            <span class="tier-tag tier-${c.atomic}" style="margin-left:0.5rem;">${c.atomic}</span>
          </h3>
          <a href="#${c.element}">Details &amp; API &rarr;</a>
        </div>
        <div class="demo-frame">
          <iframe src="${demoPath}" onload="resizeFrame(this)"></iframe>
        </div>
      </div>`;
    }

    html += `</div>`;
  }

  html += `</div>`;
  main.innerHTML = html;
}

